CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cloudpilot_arquivopublico" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titulo" varchar(200) NOT NULL, "arquivo" varchar(200) NOT NULL, "nome_original" varchar(255) NOT NULL, "tamanho" integer unsigned NOT NULL CHECK ("tamanho" >= 0), "tipo" varchar(100) NOT NULL, "enviado_em" datetime NOT NULL, "enviado_por_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_atareuniao" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titulo" varchar(200) NOT NULL, "data" date NOT NULL, "horario" time NULL, "local" varchar(200) NOT NULL, "coordenador" varchar(150) NOT NULL, "responsavel" varchar(150) NOT NULL, "conteudo" text NOT NULL CHECK ((JSON_VALID("conteudo") OR "conteudo" IS NULL)), "na_fila" bool NOT NULL, "na_fila_em" datetime NULL, "exportada_em" datetime NULL, "criada_em" datetime NOT NULL, "atualizada_em" datetime NOT NULL, "atualizada_por_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "criada_por_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_atividade" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titulo" varchar(200) NOT NULL, "data" date NOT NULL, "descricao" text NOT NULL, "imagem" varchar(100) NULL, "local_id" bigint NULL REFERENCES "core_local" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_escalatrabalho" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dia_semana" varchar(20) NULL, "horario_fim" time NULL, "horario_inicio" time NULL, "integrante_id" bigint NULL REFERENCES "core_integrante" ("id") DEFERRABLE INITIALLY DEFERRED, "local_id" bigint NULL REFERENCES "core_local" ("id") DEFERRABLE INITIALLY DEFERRED, "observacoes" text NULL, "turno" varchar(20) NOT NULL);
CREATE TABLE "core_integrante" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" varchar(150) NOT NULL, "curso" varchar(100) NULL, "foto" varchar(500) NULL, "situacao" varchar(50) NULL);
CREATE TABLE "core_local" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" varchar(150) NOT NULL, "distrito" varchar(100) NULL, "categoria" varchar(100) NOT NULL, "lat" real NOT NULL, "lon" real NOT NULL, "cor" varchar(30) NOT NULL, "icone" varchar(30) NOT NULL, "foto" varchar(500) NULL, "descricao" text NULL, "status" varchar(50) NULL);
CREATE TABLE "core_perfil" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cpf" varchar(14) NOT NULL UNIQUE, "data_nascimento" date NULL, "avatar" varchar(100) NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_usuarioautorizado" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cpf" varchar(14) NOT NULL UNIQUE, "email" varchar(254) NOT NULL UNIQUE, "nome" varchar(150) NOT NULL, "ativo" bool NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
